// Basic-OS Self-Contained Cloudflare Worker
// Serves the entire site without external dependencies

const BUNDLED_INDEX_HTML_B64 = "";

const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.ttf': 'font/ttf',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.gif': 'image/gif',
  '.webp': 'image/webp',
  '.iso': 'application/octet-stream',
  '.img': 'application/octet-stream',
  '.sh': 'text/plain; charset=utf-8',
  '.md': 'text/plain; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.wasm': 'application/wasm',
  '.bin': 'application/octet-stream',
  '.gz': 'application/gzip',
};

function getMime(path) {
  const ext = path.substring(path.lastIndexOf('.')).toLowerCase();
  return MIME_TYPES[ext] || 'application/octet-stream';
}


function base64ToUTF8(b64) {
  const binaryStr = atob(b64);
  const bytes = new Uint8Array(binaryStr.length);
  for (let i = 0; i < binaryStr.length; i++) {
    bytes[i] = binaryStr.charCodeAt(i);
  }
  return new TextDecoder('utf-8').decode(bytes);
}

addEventListener('fetch', event => {
  event.respondWith(handleRequest(event.request));
});

async function handleRequest(request) {
  const url = new URL(request.url);
  let path = url.pathname;

  // Serve main page
  if (path === '/' || path === '/index.html' || path === '/Basic-OS/' || path === '/Basic-OS/index.html') {
    const html = base64ToUTF8(BUNDLED_INDEX_HTML_B64);
    return new Response(html, {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-store, must-revalidate',
        'Access-Control-Allow-Origin': '*',
        'Cross-Origin-Opener-Policy': 'same-origin',
        'Cross-Origin-Embedder-Policy': 'require-corp',
      },
    });
  }


  // ===== TEST BOOT IMAGE =====
  if (path === "/test-boot.img") {
    const testImgB64 = "";
    const binary = Uint8Array.from(atob(testImgB64), c => c.charCodeAt(0));
    return new Response(binary, {
      headers: {
        "Content-Type": "application/octet-stream",
        "Cache-Control": "public, max-age=86400",
        "Access-Control-Allow-Origin": "*",
      }
    });
  }

  // Proxy v86 resources - hybrid approach
  // libv86.js and v86.wasm from npm (jsdelivr) for proper API
  // BIOS files and images from copy.sh
  if (path.startsWith('/v86/')) {
    const v86Path = path.substring('/v86'.length);
    let v86Url;
    if (v86Path === '/build/libv86.js' || v86Path === '/build/v86.wasm') {
      // Use npm package for core files - has proper API with add_listener etc.
      v86Url = 'https://cdn.jsdelivr.net/npm/v86@0.5.44' + v86Path;
    } else {
      // Use copy.sh for BIOS, images, and other resources
      v86Url = 'https://copy.sh/v86' + v86Path;
    }
    try {
      const resp = await fetch(v86Url);
      if (!resp.ok) return new Response('v86 resource not found', { status: 404 });
      const headers = new Headers({
        'Content-Type': getMime(v86Path),
        'Cache-Control': 'public, max-age=86400',
        'Access-Control-Allow-Origin': '*',
      });
      return new Response(resp.body, { headers });
    } catch (e) {
      return new Response('v86 proxy error: ' + e.message, { status: 503 });
    }
  }

  // BPB patching values for each ISO file
// These replace the corrupted BPB (all 0x90) with valid FAT12 geometry
const ISO_BPB_PATCH = {
  '/basic-os-64.iso':    { size: 5099520, sectors: 9960,  spf: 30 },
  '/basic-os-32.iso':    { size: 5179392, sectors: 10116, spf: 30 },
  '/basic-os-64-32.iso': { size: 5122048, sectors: 10004, spf: 30 },
};

function patchBPB(buffer, totalSectors, sectorsPerFat) {
  const data = new Uint8Array(buffer);
  // Only patch if BPB is corrupted (bytes 0x0B-0x0C are 0x90 0x90)
  if (data[0x0B] !== 0x90 || data[0x0C] !== 0x90) return buffer;
  
  const view = new DataView(buffer);
  // Bytes per sector = 512
  view.setUint16(0x0B, 512, true);
  // Sectors per cluster = 1
  data[0x0D] = 1;
  // Reserved sectors = 1
  view.setUint16(0x0E, 1, true);
  // Number of FATs = 2
  data[0x10] = 2;
  // Root entries = 224
  view.setUint16(0x11, 224, true);
  // Total sectors (16-bit) = 0
  view.setUint16(0x13, 0, true);
  // Media descriptor = 0xF0
  data[0x15] = 0xF0;
  // Sectors per FAT
  view.setUint16(0x16, sectorsPerFat, true);
  // Sectors per track = 63
  view.setUint16(0x18, 63, true);
  // Heads = 16
  view.setUint16(0x1A, 16, true);
  // Hidden sectors = 0
  view.setUint32(0x1C, 0, true);
  // Total sectors (32-bit)
  view.setUint32(0x20, totalSectors, true);
  
  return buffer;
}

// Patch the El Torito Boot Catalog pointer in the ISO 9660 Boot Record
// All three ISOs have the boot catalog pointer incorrectly set to sector 32
// The actual valid boot catalog is at sector 48
function patchBootCatalog(buffer) {
  const data = new Uint8Array(buffer);
  // Boot Record Volume Descriptor is at sector 16 (offset 0x8000)
  // Boot Catalog pointer is at offset 0x47 within the descriptor (offset 0x8047 in file)
  const BOOT_RECORD_OFFSET = 0x8000;
  const BOOT_CATALOG_PTR_OFFSET = BOOT_RECORD_OFFSET + 0x47;
  
  if (buffer.byteLength <= BOOT_CATALOG_PTR_OFFSET + 4) return buffer;
  
  const view = new DataView(buffer);
  const currentPtr = view.getUint32(BOOT_CATALOG_PTR_OFFSET, true);
  
  // Only patch if pointer is 32 (the incorrect value)
  if (currentPtr === 32) {
    view.setUint32(BOOT_CATALOG_PTR_OFFSET, 48, true); // Change to sector 48
  }
  
  return buffer;
}

  // Proxy ISO files from GitHub Pages with BPB and Boot Catalog patching
  if (path.match(/\.(iso)$/i)) {
    const isoUrl = 'https://huhubasic.github.io/Basic-OS' + path;
    try {
      const resp = await fetch(isoUrl);
      if (!resp.ok) return new Response('ISO not found', { status: 404 });
      
      // Check if this ISO needs patching
      const patchInfo = ISO_BPB_PATCH[path];
      if (patchInfo) {
        const fullBuffer = await resp.arrayBuffer();
        // Apply BPB patch (fixes corrupted FAT12 geometry)
        let patchedBuffer = patchBPB(fullBuffer, patchInfo.sectors, patchInfo.spf);
        // Apply Boot Catalog pointer patch (fixes El Torito boot catalog location: 32→48)
        patchedBuffer = patchBootCatalog(patchedBuffer);
        return new Response(patchedBuffer, {
          headers: {
            'Content-Type': 'application/octet-stream',
            'Cache-Control': 'public, max-age=86400',
            'Access-Control-Allow-Origin': '*',
            'Accept-Ranges': 'bytes',
          },
        });
      }
      
      return new Response(resp.body, {
        headers: {
          'Content-Type': 'application/octet-stream',
          'Cache-Control': 'public, max-age=86400',
          'Access-Control-Allow-Origin': '*',
          'Accept-Ranges': 'bytes',
        },
      });
    } catch (e) {
      return new Response('ISO proxy error: ' + e.message, { status: 503 });
    }
  }

  // Proxy shared resources (fonts etc.) from GitHub
  let proxyPath = path;
  if (proxyPath.startsWith('/Basic-OS')) {
    proxyPath = proxyPath.substring('/Basic-OS'.length) || '/';
  }
  if (proxyPath.startsWith('/shared/')) {
    const githubUrl = 'https://raw.githubusercontent.com/HuHuBasic/Basic-OS/main' + proxyPath;
    try {
      const resp = await fetch(githubUrl);
      if (!resp.ok) return new Response('Not Found', { status: 404 });
      return new Response(resp.body, {
        headers: {
          'Content-Type': getMime(proxyPath),
          'Cache-Control': 'public, max-age=86400',
          'Access-Control-Allow-Origin': '*',
        },
      });
    } catch (e) {
      return new Response('Service Unavailable', { status: 503 });
    }
  }

  // Fallback: return main page for SPA-like behavior
  if (proxyPath !== '/index.html') {
    const html = base64ToUTF8(BUNDLED_INDEX_HTML_B64);
    return new Response(html, {
      headers: {
        'Content-Type': 'text/html; charset=utf-8',
        'Cache-Control': 'no-store, must-revalidate',
        'Access-Control-Allow-Origin': '*',
        'Cross-Origin-Opener-Policy': 'same-origin',
        'Cross-Origin-Embedder-Policy': 'require-corp',
      },
    });
  }

  return new Response('Not Found', { status: 404 });
}
